def main() -> None:
    logging.basicConfig(
        level=logging.INFO,
        format="%(message)s",
        stream=sys.stdout,
    )

    if "--test" in sys.argv:
        _run_tests()
        return

    has_export_flags = any(
        f in sys.argv for f in {"--json", "--html", "--svg", "--export-all", "--graphml", "--cypher"}
    )

    uml_lang_flags = {
        "--c++": "cpp", "--java": "java", "--csharp": "csharp",
        "--python-classes": "python", "--go-classes": "go",
        "--rust-classes": "rust", "--php-classes": "php",
        "--kotlin": "kotlin", "--scala": "scala",
        "--swift-classes": "swift", "--dart-classes": "dart",
        "--ruby-classes": "ruby",
    }
    uml_codegen_flag: Optional[str] = None
    for flag, lang in uml_lang_flags.items():
        if flag in sys.argv:
            uml_codegen_flag = lang
            break

    if uml_codegen_flag:
        parser = build_parser()
        args = parser.parse_args()
        target = args.target
        app = readmenatorApplication()
        code = app.generate_uml_code(target, uml_codegen_flag)
        print(code)
        return

    if len(sys.argv) > 2 and sys.argv[1] != "--rebuild" and not sys.argv[1].startswith("-"):
        target = sys.argv[1]

def ensure_readmenator_installed() -> bool:
    """Check if readmenator is installed via pip; install it if missing.

    Returns True if readmenator is available after the check.
    """
    if importlib.util.find_spec("readmenator") is not None:
        return True
    logger.info("readmenator not found, installing via pip...")
    try:
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "readmenator"],
        )
        logger.info("readmenator installed successfully")
        return True
    except subprocess.CalledProcessError:
        logger.warning(
            "Failed to install readmenator automatically. "
            "Install manually: pip install readmenator"
        )
        return False

def inject(self, project_root: str) -> int:
    """Inject KB reference into all discovered agent files.

    Returns the number of agent files actually modified.
    """
    root = Path(project_root).resolve()
    targets = self._find_agent_files(root)
    modified = 0
    for path in targets:
        if self._inject_single(path):
            modified += 1
    if modified:
        logger.info(
            "Injected knowledge base reference into %d agent file(s)",
            modified,
        )
    return modified

def find_agent_files(self, project_root: str) -> List[Path]:
    """Public accessor: return all detected agent files."""
    return self._find_agent_files(Path(project_root).resolve())

def _find_agent_files(self, root: Path) -> List[Path]:
    found: List[Path] = []
    for name in self._agent_files:
        path = root / name
        if path.is_file():
            found.append(path)
    for pattern in self._agent_globs:
        matches = glob.glob(str(root / pattern), recursive=False)
        for match in sorted(matches):
            p = Path(match)
            if p.is_file() and p not in found:
                found.append(p)
    return found

def _extract_current_injection(content: str) -> str:
    start_idx = content.find(_ANCHOR)
    end_idx = content.find(_ANCHOR_END)
    if start_idx < 0 or end_idx < 0:
        return ""
    end_idx += len(_ANCHOR_END)
    return content[start_idx:end_idx]

@staticmethod

def _remove_old_injection(content: str) -> str:
    start_idx = content.find(_ANCHOR)
    end_idx = content.find(_ANCHOR_END)
    if start_idx < 0 or end_idx < 0:
        return content
    end_idx += len(_ANCHOR_END)
    before = content[:start_idx].rstrip("\n")
    after = content[end_idx:].lstrip("\n")
    return before + ("\n" + after if after else "")

def _build_injection(self, fmt: str) -> str:
    kwargs = dict(
        anchor_start=_ANCHOR,
        anchor_end=_ANCHOR_END,
        kb_filename=self._kb_filename,
        agent_output_dir=self._agent_output_dir,
        wiki_output_dir=self._wiki_output_dir,
    )
    if fmt == "plain":
        return _INJECTION_PLAIN.format(**kwargs)
    return _INJECTION_MD.format(**kwargs)

def _build_mdc_injection(self) -> str:
    """Build Cursor .mdc injection body (frontmatter added separately)."""
    return self._build_injection("markdown")

@staticmethod

def __init__(self, config: Config) -> None:
    """Store configuration for output paths and size budgets."""
    self._config = config

def _infer_subsystems(
    self, nodes: List[Node],
) -> Dict[str, List[Node]]:
    """Group nodes by directory, inferring subsystem names."""
    min_files = self._config.AGENT_OUTPUT_MIN_SUBSYSTEM_FILES
    dir_groups: Dict[str, List[Node]] = defaultdict(list)
    for node in nodes:
        parent = os.path.dirname(node.node_id)
        if not parent:
            parent = "."
        dir_groups[parent].append(node)

    subsystems: Dict[str, List[Node]] = {}
    assigned: Set[str] = set()

    for dir_path, file_nodes in sorted(
        dir_groups.items(), key=lambda kv: (-len(kv[1]), kv[0])
    ):
        if len(file_nodes) >= min_files:
            name = os.path.basename(dir_path)
            if not name or name == ".":
                name = Path(
                    self._config.OUTPUT_FILENAME
                ).stem.replace("KNOWLEDGE_BASE", "root")
            if name in subsystems:
                name = dir_path.replace("/", "_")
            subsystems[name] = file_nodes
            assigned.update(n.node_id for n in file_nodes)

    misc = [n for n in nodes if n.node_id not in assigned]
    if misc:
        subsystems["misc"] = misc

    return subsystems

def _build_index(
    self,
    nodes: List[Node],
    subsystems: Dict[str, List[Node]],
    imported_by: Optional[Dict[str, List[str]]] = None,
) -> str:
    """Build the file -> purpose -> subsystem -> blast radius table."""
    node_to_sub: Dict[str, str] = {}
    for name, members in subsystems.items():
        for n in members:
            node_to_sub[n.node_id] = name
    users = imported_by or {}

    lines = [
        "# Index",
        "",
        "| File | Purpose | Subsystem | Symbols | Used by |",
        "|------|---------|-----------|---------|---------|",
    ]
    for node in sorted(nodes, key=lambda n: n.node_id):
        purpose = escape_cell(
            file_purpose(node, self._config.AGENT_PURPOSE_MAX_CHARS)
        ) or "-"
        sub = node_to_sub.get(node.node_id, "-")
        used_by = len(set(users.get(node.node_id, [])))
        lines.append(
            f"| `{node.node_id}` | {purpose} | {sub} | "
            f"{len(node.symbols)} | {used_by} |"
        )
    lines.append("")
    return "\n".join(lines)

def _build_architecture(
    self,
    edges: List[Edge],
    resolved_edges: List[Edge],
    nodes: List[Node],
) -> str:
    """Build internal dependency pairs plus per-file external imports.

    External imports exclude raw import strings that resolved to a
    project file, so internal modules are never listed twice.
    """
    node_ids = {n.node_id for n in nodes}
    lines = [
        "# Architecture",
        "",
        "## Internal Dependencies",
        "",
    ]
    internal = sorted({
        (e.source, e.target) for e in resolved_edges
        if e.source in node_ids and e.target in node_ids
    })
    if internal:
        for source, target in internal:
            lines.append(f"- `{source}` -> `{target}`")
    else:
        lines.append("- (no internal resolved imports)")

    lines.extend([
        "",
        "## External Imports",
        "",
    ])
    resolver = ImportResolver(sorted(node_ids))
    external: Dict[str, Set[str]] = defaultdict(set)
    for e in edges:
        if e.relation not in ("imports", "resolved_imports"):
            continue
        if e.source not in node_ids or e.target in node_ids:
            continue

def _build_security(
    self, findings: List[SecurityFinding], nodes: Optional[List[Node]] = None
) -> str:
    """Build findings grouped by severity with scope and fix hints."""
    lines = ["# Security Findings", ""]
    if not findings:
        lines.append("No security findings.")
        return "\n".join(lines)

    symbols_by_file: Dict[str, List[Symbol]] = {
        n.node_id: n.symbols for n in (nodes or [])
    }
    by_severity: Dict[str, List[SecurityFinding]] = defaultdict(list)
    for f in findings:
        by_severity[f.severity].append(f)

    for sev in _SEVERITY_ORDER:
        group = by_severity.get(sev, [])
        if not group:
            continue
        lines.append(f"## {sev.upper()} ({len(group)})")
        lines.append("")
        for f in sorted(group, key=lambda x: (x.file_path, x.line)):
            cwe = f" [{f.cwe}]" if f.cwe else ""
            scope = self._enclosing_symbol(
                symbols_by_file.get(f.file_path, []), f.line,
            )
            scope_str = f" (in `{scope}`)" if scope else ""
            lines.append(
                f"- `{f.file_path}:{f.line}`{scope_str} -- {f.description}{cwe}"
            )
            lines.append(f"  Fix: {fix_hint_for(f)}")
        lines.append("")
    return "\n".join(lines)

@staticmethod

def _enclosing_symbol(symbols: List[Symbol], line: int) -> str:
    """Return the nearest symbol defined at or before line."""
    best = ""
    best_line = -1
    for sym in symbols:
        if best_line < sym.line <= line:
            best = sym.name
            best_line = sym.line
    return best

def _is_public(self, sym: Symbol) -> bool:
    """Return whether a symbol belongs in the public API listing."""
    if not self._config.AGENT_API_PUBLIC_ONLY:
        return True
    return not sym.name.startswith("_") or sym.name in _PUBLIC_DUNDERS

@staticmethod

def _qualified_names(symbols: List[Symbol]) -> Dict[int, str]:
    """Map each method's index to ``Owner.method`` using the nearest preceding type."""
    owners = sorted(
        (s.line, s.name) for s in symbols if s.kind in _CLASS_KINDS
    )
    qualified: Dict[int, str] = {}
    for index, sym in enumerate(symbols):
        if sym.kind != "method":
            continue
        owner = ""
        for line, name in owners:
            if line > sym.line:
                break
            owner = name
        if owner:
            qualified[index] = f"{owner}.{sym.name}"
    return qualified

def _inventory(self, out_dir: Path) -> List[Dict[str, object]]:
    """List generated documents with line counts and token estimates."""
    chars_per_token = max(1, self._config.AGENT_CHARS_PER_TOKEN)
    inventory: List[Dict[str, object]] = []
    for path in sorted(out_dir.rglob("*.md")):
        text = path.read_text(encoding="utf-8")
        inventory.append({
            "path": path.relative_to(out_dir).as_posix(),
            "lines": len(text.splitlines()),
            "approx_tokens": max(1, len(text) // chars_per_token),
        })
    return inventory

def _build_symbols(self, nodes: List[Node]) -> str:
    """Build grep-friendly symbol index (one line per symbol)."""
    lines = ["# Symbols", "",
             "| Symbol | Kind | File:Line | Signature |",
             "|--------|------|-----------|-----------|"]
    sig_max = self._config.AGENT_SIGNATURE_MAX_CHARS
    for node in sorted(nodes, key=lambda n: n.node_id):
        for s in sorted(node.symbols, key=lambda x: (x.name, x.line)):
            sig = escape_cell(truncate_words(s.signature or "", sig_max))
            lines.append(f"| `{s.name}` | {s.kind} | "
                         f"`{node.node_id}:{s.line}` | `{sig}` |")
    lines.append("")
    return "\n".join(lines)

@staticmethod

def _closed_loop(cycle: List[str]) -> str:
    """Render a cycle as a closed loop without duplicating a closed tail."""
    loop = list(cycle)
    if loop and loop[-1] != loop[0]:
        loop.append(loop[0])
    return " -> ".join(f"`{f}`" for f in loop)

def _build_concepts(
    self, analysis_v2: Optional[AnalysisResultV2]
) -> str:
    """Build the grep-friendly semantic concept layer."""
    graph = getattr(analysis_v2, "concept_graph", None) if analysis_v2 else None
    lines = ["# Concepts", ""]
    if graph is None or not graph.concepts:
        lines.append("No concepts extracted.")
        lines.append("")
        return "\n".join(lines)
    lines.append(
        "Nouns map atomically to file sets (EXTRACTED); "
        "verbs aggregate structural edges (INFERRED)."
    )
    lines.append("")
    for concept in graph.concepts[:50]:
        files = ", ".join(f"`{f}`" for f in sorted(concept.file_ids)[:10])
        lines.append(
            f"- `{concept.name}` | files={len(concept.file_ids)} "
            f"| mentions={concept.mention_count} | {files}"
        )
    lines.append("")
    if graph.relations:
        lines.append("## Verb Edges")
        lines.append("")
        for rel in graph.relations[:50]:
            lines.append(
                f"- `{rel.source}` --{rel.verb}--> `{rel.target}` "
                f"(strength {rel.strength:.2f})"
            )
        lines.append("")
    if graph.dialectic_questions:
        lines.append("## Dialectic")
        lines.append("")
        for question in graph.dialectic_questions:
            lines.append(f"- {question}")
        lines.append("")
    return "\n".join(lines)

@staticmethod

def _safe_name(name: str) -> str:
    """Return a filesystem-safe subsystem name."""
    return "".join(
        c if c.isalnum() or c in ("-", "_") else "_"
        for c in name
    )

def _deps_by_source(
    resolved_map: Dict[Tuple[str, str], str],
) -> Dict[str, List[str]]:
    """Index resolved dependencies by source file, sorted and deduplicated."""
    deps: Dict[str, Set[str]] = defaultdict(set)
    for (src, tgt) in resolved_map:
        deps[src].add(tgt)
    return {src: sorted(targets) for src, targets in deps.items()}

@staticmethod

def _build_resolved_map(
    resolved_edges: List[Edge],
) -> Dict[Tuple[str, str], str]:
    """Map (source, target) pairs to their relation."""
    mapping: Dict[Tuple[str, str], str] = {}
    for e in resolved_edges:
        mapping[(e.source, e.target)] = e.relation
    return mapping

@staticmethod

def _build_imported_by_map(
    resolved_edges: List[Edge],
) -> Dict[str, List[str]]:
    """Map each file to the files that import it."""
    result: Dict[str, List[str]] = defaultdict(list)
    for e in resolved_edges:
        result[e.target].append(e.source)
    return result

@staticmethod

def _page_name(filename: str, page: int) -> str:
    """Return the file name of a page (page 1 keeps the original name)."""
    if page <= 1:
        return filename
    stem, ext = os.path.splitext(filename)
    return f"{stem}{_PAGE_SUFFIX}{page}{ext}"

@staticmethod

def _split_units(body: List[str], is_table: bool) -> List[List[str]]:
    """Split a document body into atomic units that should not straddle pages."""
    if is_table:
        return [[line] for line in body]
    units: List[List[str]] = []
    for line in body:
        if line.startswith("## ") or not units:
            units.append([line])
        else:
            units[-1].append(line)
    return units

@staticmethod

def _paginate(self, filename: str, content: str) -> List[str]:
    """Split a document into pages that each respect the line cap."""
    cap = self._config.AGENT_OUTPUT_MAX_LINES
    lines = content.rstrip("\n").split("\n")
    if cap <= 0 or len(lines) <= cap:
        return [content]
    title, body = lines[0], lines[1:]
    preamble: List[str] = []
    for index, line in enumerate(body[:cap]):
        if _TABLE_RULE_RE.match(line):
            preamble, body = body[: index + 1], body[index + 1:]
            break
    is_table = bool(preamble)
    if not is_table:
        preamble = [""]
        while body and not body[0].strip():
            body = body[1:]
    budget = max(1, cap - len(preamble) - _PAGE_OVERHEAD_LINES)
    pages: List[List[str]] = [[]]
    for unit in self._split_units(body, is_table):
        for chunk in self._chunk_unit(unit, budget):
            if pages[-1] and len(pages[-1]) + len(chunk) > budget:
                pages.append([])
            pages[-1].extend(chunk)
    total = len(pages)
    names = [self._page_name(filename, i + 1) for i in range(total)]
    rendered: List[str] = []
    for i, chunk in enumerate(pages):
        head = [f"{title} (page {i + 1} of {total})"]
        if i == 0:
            head.append("Pages: " + ", ".join(f"[{n}]({n})" for n in names))
        else:
