def _resolve_imports(
    self, nodes: List[Node], edges: List[Edge], target_dir: str
) -> List[Edge]:
    file_ids = [n.node_id for n in nodes]
    resolver = ImportResolver(file_ids, target_dir)
    resolved: List[Edge] = []
    for edge in edges:
        target = resolver.resolve(edge.target, edge.source)
        if target is not None and target != edge.source:
            resolved.append(
                Edge(
                    source=edge.source,
                    target=target,
                    relation="resolved_imports",
                    confidence="EXTRACTED",
                )
            )
    return resolved

def _maybe_refresh_pages(self, root: Path) -> None:
    """Refresh the static docs site when a previous ``pages`` run created it.

    The site directory is only rewritten when it already holds a
    readmenator gallery (index plus maps subdirectory), so a user's own
    docs folder is never taken over by a plain rebuild.
    """
    if not self._config.SITE_REFRESH_ON_REBUILD:
        return
    site = root / self._config.DIAGRAM_PAGES_DIR
    maps_dir = site / self._config.DIAGRAM_MAPS_SUBDIR.strip().strip("/")
    if not (site / "index.html").is_file() or not maps_dir.is_dir():
        return
    try:
        self.export_pages(str(root), full=True)
    except Exception:
        logger.warning("Documentation site refresh failed", exc_info=True)

def _maybe_publish_github_wiki(self, root: Path) -> None:
    """Publish generated docs to the GitHub wiki on every run of a git checkout.

    Skipped when GH_WIKI_ENABLED is off or the root is not a git
    repository; publish failures are logged and never fail the run.
    """
    if not self._config.GH_WIKI_ENABLED:
        return
    if not read_git_head(str(root))["commit"]:
        return
    try:
        result = self.publish_github_wiki(str(root))
    except Exception:
        logger.warning("GitHub wiki publish failed", exc_info=True)
        return
    if not result.pushed and "up to date" not in result.message:
        logger.warning("%s", result.message)

