def audit_deep(self, target_dir: str) -> AnalysisResultV2:
    nodes, edges, content_map = self._scan_with_content(target_dir)
    resolved_edges = self._last_resolved_edges
    layers = LayerDetector().detect(nodes, edges)
    result = self._deep_runner.run(nodes, edges, resolved_edges, layers, content_map)
    if result.taint:
        logger.info("Taint paths: %d", len(result.taint.paths))
    if result.cycles:
        logger.info("Dependency cycles: %d", len(result.cycles))
    if result.hotspots:
        logger.info(
            "Top hotspot: %s",
            result.hotspots[0].file_id if result.hotspots else "none",
        )
    if result.layer_violations:
        logger.info("Layer violations: %d", len(result.layer_violations))
    if result.suggested_rules:
        logger.info("Suggested rules: %d", len(result.suggested_rules))
    return result

def load(self) -> Dict[str, str]:
    if not self._cache_path.is_file():
        return {}
    try:
        data = json.loads(self._cache_path.read_text(encoding="utf-8"))
        if isinstance(data, dict):
            return data
    except (json.JSONDecodeError, OSError):
        pass
    return {}

def save(self, hashes: Dict[str, str]) -> None:
    self._cache_dir.mkdir(parents=True, exist_ok=True)
    self._cache_path.write_text(
        json.dumps(hashes, indent=2, sort_keys=True), encoding="utf-8"
    )

def compute_hash(self, file_path: Path) -> str:
    hasher = hashlib.sha256()
    try:
        data = file_path.read_bytes()
        hasher.update(data)
    except OSError:
        return ""
    return hasher.hexdigest()

def compute_hashes(self, file_paths: Dict[str, Path]) -> Dict[str, str]:
    result: Dict[str, str] = {}
    for rel_path, abs_path in file_paths.items():
        h = self.compute_hash(abs_path)
        if h:
            result[rel_path] = h
    return result

def find_changed(self, file_paths: Dict[str, Path]) -> Set[str]:
    cached = self.load()
    changed: Set[str] = set()
    for rel_path, abs_path in file_paths.items():
        if rel_path not in cached:
            changed.add(rel_path)
            continue
        current_hash = self.compute_hash(abs_path)
        if current_hash and current_hash != cached[rel_path]:
            changed.add(rel_path)
    return changed

def prune_deleted(self, current_file_ids: Set[str]) -> None:
    cached = self.load()
    pruned = {k: v for k, v in cached.items() if k in current_file_ids}
    if len(pruned) != len(cached):
        self.save(pruned)
        self._prune_analysis_cache(current_file_ids)

# ------------------------------------------------------------------
# Analysis result caching (semantic cache)
# ------------------------------------------------------------------

def save_analysis(
    self,
    key: str,
    data: Dict[str, Any],
) -> None:
    """Save an analysis result to the semantic cache.

    Args:
        key: Cache key (e.g. "security", "analysis_v2", "taint").
        data: Serializable analysis data.
    """
    self._cache_dir.mkdir(parents=True, exist_ok=True)
    cache: Dict[str, Any] = {}
    if self._analysis_cache_path.is_file():
        try:
            cache = json.loads(self._analysis_cache_path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            pass
    cache[key] = data
    self._analysis_cache_path.write_text(
        json.dumps(cache, indent=2, default=str), encoding="utf-8"
    )

def load_analysis(self, key: str) -> Optional[Dict[str, Any]]:
    """Load a previously cached analysis result.

    Args:
        key: Cache key.

    Returns:
        Cached data dict, or None if not found or expired.
    """
    if not self._analysis_cache_path.is_file():
        return None
    try:
        cache = json.loads(self._analysis_cache_path.read_text(encoding="utf-8"))
        return cache.get(key)
    except (json.JSONDecodeError, OSError):
        return None

def clear_analysis(self, key: Optional[str] = None) -> None:
    """Clear analysis cache, optionally for a specific key only.

    Args:
        key: If given, only clears this key. Otherwise clears all.
    """
    if not self._analysis_cache_path.is_file():
        return
    try:
        if key is None:
            self._analysis_cache_path.unlink(missing_ok=True)
        else:
            cache = json.loads(self._analysis_cache_path.read_text(encoding="utf-8"))
            cache.pop(key, None)
            self._analysis_cache_path.write_text(
                json.dumps(cache, indent=2, default=str), encoding="utf-8"
            )
    except (json.JSONDecodeError, OSError):
        pass

def _prune_analysis_cache(self, current_file_ids: Set[str]) -> None:
    """Remove analysis entries for files that no longer exist."""
    cache = self.load_analysis("file_level")
    if not cache:
        return
    pruned = {
        fid: data for fid, data in cache.get("findings", {}).items()
        if fid in current_file_ids
    }
    self.save_analysis("file_level", {"findings": pruned})

def weight(self) -> float:
    """Effective weight for ranking = semantic weight * confidence."""
    return EDGE_WEIGHTS.get(self.kind, 0.5) * self.confidence

def __init__(self) -> None:
    self._objects: Set[str] = set()
    self._morphisms: List[Morphism] = []
    self._outgoing: Dict[str, List[Morphism]] = {}
    self._incoming: Dict[str, List[Morphism]] = {}

def objects(self) -> Set[str]:
    return self._objects

@property

def compose(self, a: Morphism, b: Morphism) -> Optional[Morphism]:
    """Compose two morphisms if target of a matches source of b.

    Returns a new Morphism with composite kind, or None if
    the kinds are incompatible.
    """
    if a.target == b.source:
        composite_kind = self._compose_kind(a.kind, b.kind)
        if composite_kind is not None:
            return Morphism(
                source=a.source,
                target=b.target,
                kind=composite_kind,
                confidence=a.confidence * b.confidence,
            )
    return None

def paths(
    self, source: str, target: str, max_depth: int = 10
) -> List[List[Morphism]]:
    """Find all composition paths from source to target up to max_depth."""
    results: List[List[Morphism]] = []

    def dfs(
        current: str, goal: str, path: List[Morphism], depth: int
    ) -> None:
        if depth > max_depth:
            return
        if current == goal and path:
            results.append(list(path))
            return
        for m in self._outgoing.get(current, []):
            if m not in path:
                path.append(m)
                dfs(m.target, goal, path, depth + 1)
                path.pop()

    dfs(source, target, [], 0)
    return results

@staticmethod

def __init__(self, category: Category) -> None:
    self._category = category
    self._node_list: List[str] = sorted(category.objects)
    self._node_index: Dict[str, int] = {
        n: i for i, n in enumerate(self._node_list)
    }
    self._out_weights: Dict[str, float] = {}
    self._compute_out_weights()

def _compute_out_weights(self) -> None:
    for obj in self._category.objects:
        total = sum(m.weight for m in self._category.outgoing(obj))
        self._out_weights[obj] = total if total > 0 else 0.0

@property

def nodes(self) -> List[str]:
    return list(self._node_list)

@property

def transition_weight(self, source: str, target: str) -> float:
    """Sum of weights of all morphisms from source to target."""
    total = 0.0
    for m in self._category.outgoing(source):
        if m.target == target:
            total += m.weight
    return total

def stochastic_row(self, source: str) -> Dict[str, float]:
    """Return dict of target -> probability for the row of *source*.

    Probabilities sum to 1.0 if source has outgoing edges.
    Returns empty dict for dangling nodes.
    """
    total = self._out_weights.get(source, 0.0)
    if total == 0.0:
        return {}
    result: Dict[str, float] = {}
    for m in self._category.outgoing(source):
        result[m.target] = result.get(m.target, 0.0) + (m.weight / total)
    return result

def _infer_edge_kind(relation: str) -> EdgeKind:
    """Map a relation string to an EdgeKind.

    Falls back to DEPENDS_ON for unrecognised strings.
    """
    try:
        return EdgeKind(relation)
    except ValueError:
        return EdgeKind.DEPENDS_ON

def verb_for_relation(relation: str) -> str:
    """Return the verb label for a structural edge relation."""
    return _VERB_BY_RELATION.get(relation, "bridges")

def __init__(self, config: Config) -> None:
