    """Generate deterministic thesis/antithesis/synthesis prompts."""
    questions: List[str] = []
    by_name: Dict[str, ConceptNode] = {c.name: c for c in concepts}
    verbs: Dict[Tuple[str, str], str] = {}
    for rel in relations:
