def _tokens(text: str) -> Counter:
    """Tokenize scan text into a lowercase term counter."""
    return Counter(match.group(0).lower() for match in _TOKEN_RE.finditer(text or ""))

def _jaccard(left: Counter, right: Counter) -> float:
    """Compute Jaccard similarity between two token counters."""
    if not left or not right:
        return 0.0
    left_keys = set(left)
    right_keys = set(right)
    union = left_keys | right_keys
    if not union:
        return 0.0
    return len(left_keys & right_keys) / len(union)

def dependencies_available(self) -> bool:
    """Return True when sentence-transformers is importable."""
    try:
        __import__("sentence_transformers")
        return True
    except ImportError:
        return False

def cluster_jaccard(
    self, corpus: Dict[str, str], threshold: float = 0.08
) -> List[List[str]]:
    """Group files into similarity clusters with union-find.

    Args:
        corpus: Mapping of file identifier to scan text.
        threshold: Minimum Jaccard similarity to link two files.

    Returns:
        Clusters with at least EMBED_MIN_CLUSTER_SIZE members.
    """
    files = sorted(corpus)
    tokenized = {file_id: _tokens(corpus[file_id]) for file_id in files}
    parent = {file_id: file_id for file_id in files}

def find(item: str) -> str:
    """Find the union-find root for an item."""
    while parent[item] != item:
        parent[item] = parent[parent[item]]
        item = parent[item]
    return item

def union(left: str, right: str) -> None:
    """Merge two union-find sets."""
    parent[find(left)] = find(right)

for index, left in enumerate(files):
    for right in files[index + 1 :]:
        if _jaccard(tokenized[left], tokenized[right]) >= threshold:
            union(left, right)
groups: Dict[str, List[str]] = {}
for file_id in files:
    groups.setdefault(find(file_id), []).append(file_id)
return sorted(
    [sorted(members) for members in groups.values() if len(members) >= self._config.EMBED_MIN_CLUSTER_SIZE],
    key=lambda members: (-len(members), members[0] if members else ""),
)

def project_jaccard(self, corpus: Dict[str, str]) -> List[Dict[str, Any]]:
    """Project files to 2D with a deterministic radial layout.

    Args:
        corpus: Mapping of file identifier to scan text.

    Returns:
        Points normalized to the [-1, 1] square.
    """
    files = sorted(corpus)
    if not files:
        return []
    tokenized = {file_id: _tokens(corpus[file_id]) for file_id in files}
    totals = {file_id: max(1, sum(tokenized[file_id].values())) for file_id in files}
    points = []
    for index, file_id in enumerate(files):
        angle = 2.0 * math.pi * index / max(1, len(files))
        radius = min(1.0, math.log2(totals[file_id] + 1) / 8.0)
        points.append(
            {
                "file": file_id,
                "x": round(radius * math.cos(angle), 4),
                "y": round(radius * math.sin(angle), 4),
            }
        )
    return points

def matches(self, file_path: str, rule_id: str) -> bool:
    """Return True when this entry suppresses the finding.

    Args:
        file_path: Finding file path to test.
        rule_id: Finding rule identifier to test.

    Returns:
        True when both the path glob and rule match.
    """
    if self.rule_id not in ("*", rule_id):
        return False
    return fnmatch.fnmatch(file_path, self.pattern) or fnmatch.fnmatch(
        file_path.split("/")[-1], self.pattern
    )

def entries(self) -> List[ExclusionEntry]:
    """Return the loaded exclusion entries."""
    return list(self._entries)

def parse_exclusions(text: str) -> List[ExclusionEntry]:
    """Parse the minimal exclusions YAML into entries.

    Args:
        text: Raw YAML content with `exclusions:` list items.

    Returns:
        Parsed exclusion entries.
    """
    entries: List[ExclusionEntry] = []
    current: Dict[str, str] = {}
    for raw_line in text.splitlines():
        line = raw_line.rstrip()
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or stripped == "exclusions:":
            continue
        if stripped.startswith("- "):
            if current:
                entries.append(_to_entry(current))
            current = {}
            rest = stripped[2:].strip()
            if ": " in rest:
                key, value = rest.split(": ", 1)
                current[key.strip()] = _unquote(value.strip())
        elif ": " in stripped and current is not None:
            key, value = stripped.split(": ", 1)
            current[key.strip()] = _unquote(value.strip())
    if current:
        entries.append(_to_entry(current))
    return entries

def _to_entry(data: Dict[str, str]) -> ExclusionEntry:
    """Convert a raw mapping into an exclusion entry."""
    pattern = data.get("pattern") or data.get("path") or data.get("sha256") or "*"
    return ExclusionEntry(
        pattern=pattern,
        rule_id=data.get("rule_id", "*") or "*",
        reason=data.get("reason", ""),
        reclassified_as=data.get("reclassified_as", ""),
    )

def _unquote(value: str) -> str:
    """Strip matching single or double quotes from a scalar."""
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        return value[1:-1]
    return value

