@staticmethod

def detect_cycles(
    self,
    nodes: List[Node],
    resolved_edges: Optional[List[Edge]] = None,
) -> List[DependencyCycle]:
    """Detect cycles in the resolved import graph using DFS.

    Uses Tarjan's algorithm variant with three-colour DFS to find
    all elementary cycles. Returns each cycle as a DependencyCycle.
    """
    if not nodes or not resolved_edges:
        return []

    adj: Dict[str, List[str]] = defaultdict(list)
    file_ids: Set[str] = {n.node_id for n in nodes}
    for edge in resolved_edges:
        if edge.source in file_ids and edge.target in file_ids:
            adj[edge.source].append(edge.target)

    cycles: List[DependencyCycle] = []
    WHITE, GRAY, BLACK = 0, 1, 2
    color: Dict[str, int] = {}
    parent: Dict[str, Optional[str]] = {}

def _dfs_visit(current: str) -> None:
    color[current] = GRAY
    for neighbor in adj.get(current, []):
        if neighbor not in color:
            color[neighbor] = WHITE
            parent[neighbor] = current
            _dfs_visit(neighbor)
        elif color[neighbor] == GRAY:
            _record_cycle(neighbor, current)
    color[current] = BLACK

def _record_cycle(start: str, end: str) -> None:
    cycle_path: List[str] = [start]
    node: Optional[str] = end
    while node is not None and node != start:
        cycle_path.append(node)
        node = parent.get(node)
    if node == start or not node:
        cycle_path.append(start)
    cycle_path.reverse()
    if len(cycle_path) >= 3:
        deduped: List[str] = []
        seen_in_cycle: Set[str] = set()
        for n in cycle_path:
            if n not in seen_in_cycle:
                seen_in_cycle.add(n)
                deduped.append(n)
        if len(deduped) >= 2:
            cycles.append(
                DependencyCycle(cycle=list(deduped), length=len(deduped))
            )

for n in nodes:
    if n.node_id not in color:
        color[n.node_id] = WHITE
        parent[n.node_id] = None
        _dfs_visit(n.node_id)

cycles.sort(key=lambda c: c.length, reverse=True)
return cycles

def analyze_change_impact(
    self,
    nodes: List[Node],
    resolved_edges: Optional[List[Edge]] = None,
) -> List[ChangeImpact]:
    """Compute change impact for every file in the project.

    For each file, finds all files that would be affected if it
    changed (direct and transitive dependents via reverse import
    graph traversal).
    """
    if not nodes:
        return []

    rev_adj: Dict[str, Set[str]] = defaultdict(set)
    file_ids: Set[str] = {n.node_id for n in nodes}
    for edge in resolved_edges or []:
        if edge.source in file_ids and edge.target in file_ids:
            rev_adj[edge.target].add(edge.source)

    max_depth = self._config.CHANGE_IMPACT_MAX_DEPTH
    max_files = self._config.CHANGE_IMPACT_MAX_FILES
    results: List[ChangeImpact] = []

    for node in nodes:
        dependents: Set[str] = set()
        visited: Set[str] = {node.node_id}
        queue: deque = deque()
        queue.append((node.node_id, 0))

        while queue and len(dependents) < max_files:
            current, depth = queue.popleft()
            if depth >= max_depth:
                continue
            for dependent in rev_adj.get(current, set()):
                if dependent not in visited:
                    visited.add(dependent)
                    dependents.add(dependent)
                    queue.append((dependent, depth + 1))

class LayerRuleEngine:
    """Architectural layer violation detection engine.

    Defines a set of permitted and forbidden layer-to-layer import
    rules. Scans all resolved import edges and flags violations
    where one layer imports from another in a way that violates
    the architecture.
    """

    FORBIDDEN_EDGES: Set[Tuple[str, str]] = {
        ("testing", "presentation"),
        ("presentation", "data_access"),
    }

    ALLOWED_EDGES: Set[Tuple[str, str]] = {
        ("testing", "business_logic"),
        ("testing", "infrastructure"),
        ("testing", "data_access"),
    }

    WARN_EDGES: Set[Tuple[str, str]] = {
        ("data_access", "presentation"),
        ("infrastructure", "presentation"),
    }

def violation_summary(violations: List[LayerViolation]) -> Dict[str, int]:
    """Summarise violations by severity."""
    summary: Dict[str, int] = {}
    for v in violations:
        summary[v.severity] = summary.get(v.severity, 0) + 1
    return summary

def detect(
    self, nodes: List[Node], edges: List[Edge]
) -> Dict[str, str]:
    """Assign each file node to an architectural layer.

    Args:
        nodes: Scanned file nodes.
        edges: Import edges.

    Returns:
        Dict mapping node_id to layer name.
    """
    imports_by_file: Dict[str, Set[str]] = defaultdict(set)
    for edge in edges:
        if edge.relation == "imports":
            imports_by_file[edge.source].add(edge.target)
    layers: Dict[str, str] = {}
    for node in nodes:
        layer = self._classify_file(
            node, edges, imports_by_file.get(node.node_id, set()),
        )
        layers[node.node_id] = layer
    return layers

@classmethod

def _path_tokens(cls, node_id: str) -> List[str]:
    """Split a path into lowercase word tokens, honoring camelCase."""
    spaced = cls._CAMEL_RE.sub("_", node_id).lower()
    return [t for t in cls._TOKEN_SPLIT_RE.split(spaced) if t]

@classmethod

def _pattern_hits(cls, pattern: str, tokens: List[str], joined: str) -> bool:
    """Return whether a layer pattern matches path tokens as a whole word.

    Short patterns (``ui``, ``di``, ``api``) must equal a token;
    longer ones also match token prefixes (``tests``, ``views``).
    Multi-word patterns match underscore-joined token runs.
    """
    if "_" in pattern:
        return f"_{pattern}_" in f"_{joined}_"
    if len(pattern) < cls._PREFIX_MIN_LEN:
        return pattern in tokens
    return any(t == pattern or t.startswith(pattern) for t in tokens)

@classmethod

def _import_roots(cls, imports: Set[str]) -> Set[str]:
    """Return the top-level module names of raw import strings."""
    roots: Set[str] = set()
    for imp in imports:
        parts = [p for p in cls._MODULE_SPLIT_RE.split(imp.lower()) if p]
        if parts:
            roots.add(parts[0])
            roots.add(parts[-1])
    return roots

def _classify_file(
    self,
    node: Node,
    edges: List[Edge],
    imports: Optional[Set[str]] = None,
) -> str:
    """Classify a single file into an architectural layer.

    Path words score one point each, framework imports three, and
    test-file naming five. Layers in _EVIDENCE_REQUIRED_LAYERS only
    accept framework points when the path already points there, so a
    CLI that imports ``unittest`` to run the suite stays production code.
    """
    tokens = self._path_tokens(node.node_id)
    joined = "_".join(tokens)
    scores: Dict[str, int] = {
        "presentation": 0,
        "business_logic": 0,
        "data_access": 0,
        "infrastructure": 0,
        "testing": 0,
    }

    for layer, patterns in self._LAYER_PATTERNS.items():
        for pattern in patterns:
            if self._pattern_hits(pattern, tokens, joined):
                scores[layer] += 1

    if node.label.lower().startswith("test") or "_test" in node.label.lower():
        scores["testing"] += 5

    if imports is None:
        imports = {
            e.target for e in edges
            if e.source == node.node_id and e.relation == "imports"
        }
    roots = self._import_roots(imports)
    for fw, layer in self._FRAMEWORK_LAYERS.items():
        if fw not in roots:
            continue

class ArchitectureLinter:
    """Enforces architectural rules over scanned nodes and edges.

    Checks file length, cross-layer import violations, and circular
    dependencies. Returns structured LinterViolation instances for
    each detected issue.
    """

    FORBIDDEN_IMPORTS: Dict[str, Set[str]] = {
        "presentation": {"data_access", "repository", "database", "dao", "orm", "migration"},
        "testing": {"presentation"},
    }

def _check_file_length(
    self,
    nodes: List[Node],
    content_map: Optional[Dict[str, str]] = None,
) -> List[LinterViolation]:
    """Check files against maximum line count threshold."""
    violations: List[LinterViolation] = []
    max_lines = self._config.LINTER_MAX_LINES
    for node in nodes:
        line_count = 0
        if content_map and node.node_id in content_map:
            line_count = len(content_map[node.node_id].splitlines())
        else:
            try:
                file_path = Path(node.node_id)
                if file_path.is_file():
                    with open(file_path, "r", encoding="utf-8", errors="ignore") as f:
                        line_count = sum(1 for _ in f)
            except (OSError, UnicodeDecodeError):
                continue
        if line_count > max_lines:
            violations.append(
                LinterViolation(
                    file_path=node.node_id,
                    rule_id="ARC001",
                    severity="warning",
                    message=f"File exceeds {max_lines} lines ({line_count} lines). Consider modularization.",
                )
            )
    return violations

def _check_cross_layer_violations(
    self,
    nodes: List[Node],
    edges: List[Edge],
    resolved_edges: Optional[List[Edge]],
    layers: Dict[str, str],
) -> List[LinterViolation]:
    """Check for forbidden cross-layer imports."""
    violations: List[LinterViolation] = []
    all_edges = edges + (resolved_edges or [])
    for edge in all_edges:
        source_layer = layers.get(edge.source)
        target_layer = layers.get(edge.target)
        if source_layer is None or target_layer is None:
            continue
        if source_layer == target_layer:
            continue
        if source_layer == "utility" or target_layer == "utility":
            continue
        forbidden = self.FORBIDDEN_IMPORTS.get(source_layer, set())
        if target_layer in forbidden:
            violations.append(
                LinterViolation(
                    file_path=edge.source,
                    rule_id="ARC002",
                    severity="error",
                    message=f"{source_layer} layer must not import {target_layer} layer. Found edge: {edge.source} -> {edge.target}",
                )
            )
    return violations

def _check_circular_dependencies(
    self,
    nodes: List[Node],
    resolved_edges: Optional[List[Edge]],
) -> List[LinterViolation]:
    """Check for circular dependencies in the resolved import graph."""
    if not resolved_edges:
        return []
    violations: List[LinterViolation] = []
    file_ids: Set[str] = {n.node_id for n in nodes}
    adj: Dict[str, List[str]] = {}
    for edge in resolved_edges:
        if edge.source in file_ids and edge.target in file_ids:
            adj.setdefault(edge.source, []).append(edge.target)
    WHITE, GRAY, BLACK = 0, 1, 2
    color: Dict[str, int] = {}
    parent: Dict[str, Optional[str]] = {}
    cycles_found: List[List[str]] = []

def _dfs(current: str) -> None:
    color[current] = GRAY
    for neighbor in adj.get(current, []):
        if neighbor not in color:
            color[neighbor] = WHITE
            parent[neighbor] = current
            _dfs(neighbor)
        elif color[neighbor] == GRAY:
            cycle: List[str] = [neighbor]
            node: Optional[str] = current
            while node is not None and node != neighbor:
                cycle.append(node)
                node = parent.get(node)
            if node == neighbor:
                cycle.append(neighbor)
            cycle.reverse()
            if len(cycle) >= 2:
                cycles_found.append(cycle)
    color[current] = BLACK

for n in nodes:
    if n.node_id not in color:
