    fi = self._fan_in.get(node.node_id, 0)
    fo = self._fan_out.get(node.node_id, 0)
    has_tests = node.node_id in self._test_files
    risk_score = fi * 2 + fo + len(node.symbols) * 0.5
    if has_tests:
        risk_score *= 0.5
    if risk_score > 0 or node.doc:
        return node
    return None

