def _find_justification_paths(
    self,
    target: str,
    seed_ids: List[str],
    category: Category,
    max_paths: int = 3,
) -> List[List[str]]:
    """Find shortest paths from any seed to target."""
    paths: List[List[str]] = []
    for seed in seed_ids:
        if seed == target:
            paths.append([seed])
            continue
        found = category.paths(seed, target, max_depth=8)
        for p in found:
            node_chain = [seed]
            for m in p:
                node_chain.append(m.target)
            paths.append(node_chain)
            if len(paths) >= max_paths:
                break
        if len(paths) >= max_paths:
            break
    return paths

def _extract_current_injection(content: str) -> str:
    start_idx = content.find(_ANCHOR_START)
    end_idx = content.find(_ANCHOR_END)
    if start_idx < 0 or end_idx < 0:
        return ""
    end_idx += len(_ANCHOR_END)
    return content[start_idx:end_idx]

@staticmethod

def _remove_old_injection(content: str) -> str:
    start_idx = content.find(_ANCHOR_START)
    end_idx = content.find(_ANCHOR_END)
    if start_idx < 0 or end_idx < 0:
        return content
    end_idx += len(_ANCHOR_END)
    before = content[:start_idx].rstrip("\n")
    after = content[end_idx:].lstrip("\n")
    return before + ("\n" + after if after else "")

