def _extract_params(signature: str) -> str:
    if not signature:
        return ""
    paren = signature.find("(")
    if paren < 0:
        return ""
    close = signature.find(")")
    if close < 0:
        close = len(signature)
    return signature[paren + 1:close].strip()

