def _code_tint(line: str) -> Tuple[int, int, int]:
    """Single-color tint for a source line: comments dim, code bright."""
    s = line.strip()
    if not s:
        return FAINT
    if s[:1] in ("#", '"', "'") or s.startswith(("//", "/*", "*", "<!--", "--")):
        return FAINT
    return TXT

